namespace NotificationsApp.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private int _nextId = 1;
    private readonly List<Notification> _notifications = new();
    private readonly Lock _lock = new();

    public NotificationService()
    {
        // Seed with initial fake data.
        _notifications.AddRange(new[]
        {
            CreateNotification("Welcome to the app!"),
            CreateNotification("Your profile was updated."),
            CreateNotification("New feature: dark mode is available.")
        });
    }

    /// <summary>Returns all notifications created up to this point.</summary>
    public Task<List<Notification>> GetNotificationsAsync()
    {
        lock (_lock)
        {
            return Task.FromResult(_notifications.ToList());
        }
    }

    /// <summary>Returns only notifications with an Id greater than <paramref name="sinceId"/>.</summary>
    public Task<List<Notification>> GetNotificationsSinceAsync(int sinceId)
    {
        lock (_lock)
        {
            return Task.FromResult(
                _notifications.Where(n => n.Id > sinceId).ToList());
        }
    }

    /// <summary>
    /// Simulates external activity by occasionally adding a notification.
    /// Called internally; in a real app new data would arrive from a database or message bus.
    /// </summary>
    public void SimulateIncoming()
    {
        lock (_lock)
        {
            // ~30 % chance of a new notification each call.
            if (Random.Shared.Next(0, 10) < 3)
            {
                string[] samples =
                [
                    "You have a new follower.",
                    "Someone commented on your post.",
                    "Your subscription is about to expire.",
                    "Server maintenance scheduled tonight.",
                    "You earned a new badge!"
                ];

                _notifications.Add(
                    CreateNotification(samples[Random.Shared.Next(samples.Length)]));
            }
        }
    }

    private Notification CreateNotification(string message)
        => new(Interlocked.Increment(ref _nextId), message, DateTime.UtcNow);
}

@page "/notifications"
@rendermode InteractiveServer

@using NotificationsApp.Services
@inject NotificationService NotificationSvc
@inject PersistentComponentState PersistState
@implements IAsyncDisposable

<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    <span class="badge bg-primary rounded-pill">@_notifications.Count</span>
</h1>

@if (_notifications.Count == 0)
{
    <p><em>No notifications yet.</em></p>
}
else
{
    <ul class="list-group">
        @foreach (var n in _notifications.OrderByDescending(x => x.Id))
        {
            <li class="list-group-item d-flex justify-content-between align-items-start">
                <span>@n.Message</span>
                <small class="text-muted">@n.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    private List<Notification> _notifications = new();
    private CancellationTokenSource? _cts;
    private PersistingComponentStateSubscription _persistSub;
    private bool _pollingStarted;

    protected override async Task OnInitializedAsync()
    {
        // Try to restore state that was persisted during prerendering.
        // If found, we skip the service call entirely — no duplicate fetch.
        _persistSub = PersistState.RegisterOnPersisting(PersistNotifications);

        if (PersistState.TryTakeFromJson<List<Notification>>(
                nameof(_notifications), out var restored))
        {
            _notifications = restored!;
        }
        else
        {
            // First (prerender) execution — load from the service.
            _notifications = await NotificationSvc.GetNotificationsAsync();
        }
    }

    private Task PersistNotifications()
    {
        PersistState.PersistAsJson(nameof(_notifications), _notifications);
        return Task.CompletedTask;
    }

    protected override void OnAfterRender(bool firstRender)
    {
        // OnAfterRender is never called during static SSR prerendering,
        // so this is safe to use as the "now interactive" signal.
        if (firstRender && !_pollingStarted)
        {
            _pollingStarted = true;
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            try
            {
                await Task.Delay(TimeSpan.FromSeconds(5), ct);
            }
            catch (TaskCanceledException)
            {
                break;
            }

            // Simulate external activity, then fetch anything new.
            NotificationSvc.SimulateIncoming();

            int maxId = _notifications.Count > 0
                ? _notifications.Max(n => n.Id)
                : 0;

            var newer = await NotificationSvc.GetNotificationsSinceAsync(maxId);
            if (newer.Count > 0)
            {
                _notifications.AddRange(newer);
                await InvokeAsync(StateHasChanged);
            }
        }
    }

    public async ValueTask DisposeAsync()
    {
        _persistSub.Dispose();

        if (_cts is not null)
        {
            await _cts.CancelAsync();
            _cts.Dispose();
        }
    }
}

